def output_to_abs_in_idx(idx):
    return (idx * 6) - 14

def get_homopolymer_len(string, idx):
    ''' Get the number of repeating characters at the given idx '''
    if not string or idx < 0 or idx >= len(string):
        return 0, 0, 0
        
    begin = end = idx
    char = string[idx]
    length = 1

    while (begin > 0 and string[begin - 1] == char):
        length = length + 1
        begin = begin - 1
    
    while (end < len(string) - 1) and string[end + 1] == char:
        length = length + 1
        end = end + 1

    return (length, begin, end)

