# 1. Grab the raw signal exactly like you do in Test_Inputs_new.py
raw_stndrd_signal = first_read.signal

chunksize = 4000
overlap = 400
step_size = chunksize - overlap

for chunk_idx, chunk_start in enumerate(range(0, len(raw_stndrd_signal) - chunksize + 1, step_size)):
    if chunk_idx >= 5: 
        break
        
    chunk_end = chunk_start + chunksize
    chunk = raw_stndrd_signal[chunk_start:chunk_end].copy()
    
    device = "cuda" if torch.cuda.is_available() else "cpu"
    # FIX 1: Use model_dtype instead of torch.float32
    clean_input = torch.tensor(chunk, dtype=model_dtype).view(1, 1, chunksize).to(device)
    
    with model.trace(clean_input):
        clean_output_proxy = model.output.save()
        
    clean_logits = clean_output_proxy.detach()
    clean_str = bonito_model.decode(clean_logits[:, 0, :])
    
    # Use the exact same Viterbi extraction from find_kmers.py
    viterbi_tensor = bonito_model._orig_mod.seqdist.viterbi(clean_logits.to(dtype=torch.float32))
    
    # Flatten it into a standard Python list
    viterbi_path = viterbi_tensor.flatten().tolist()
    
    # Append -1 to match your original find_kmers logic
    viterbi_path.append(-1)


    isolated_candidates = []
    last_state = -1
    slice_start = 0
    slice_length = 0
    
    for t in range(len(viterbi_path)):
        current_state = viterbi_path[t]
        if current_state == 0: 
            continue
            
        if current_state == last_state:
            slice_length += 1
        else:
            if 0 < slice_length <= 3:
                base = alphabet.get(last_state, "")
                isolated_candidates.append({
                    'base': base,
                    'start_t': slice_start,
                    'end_t': t,
                    'raw_start': output_to_abs_in_idx(slice_start),
                    'raw_end': output_to_abs_in_idx(t)
                })
            
            slice_start = t
            slice_length = 1
        last_state = current_state

    scales = [0.1, 0.2, 0.3, 0.4] 
    
    for cand in isolated_candidates:
        start_idx = cand['raw_start']
        end_idx = cand['raw_end']
        
        if start_idx < 0 or end_idx >= 4000:
            continue
            
        for scale in scales:
            
            # 1. APPLY NOISE FIRST (Create corrupted_input)
            corrupted_chunk = chunk.copy()
            hetero_len = end_idx - start_idx
            dampen_radius = max(1, int((hetero_len / 2) * 1.0)) 
            midpoint = (start_idx + end_idx) // 2
            local_mean = np.mean(corrupted_chunk[midpoint - dampen_radius : midpoint + dampen_radius])
            
            corrupted_chunk[midpoint - dampen_radius : midpoint + dampen_radius] = ( 
                (corrupted_chunk[midpoint - dampen_radius : midpoint + dampen_radius] * scale) 
                + (local_mean * (1-scale))
            )
            corrupted_input = torch.tensor(corrupted_chunk, dtype=model_dtype).view(1, 1, chunksize).to(device)

            # 2. MATCH RUN_PATCHES.PY CHOPPING LOGIC EXACTLY
            abs_start = chunk_start + start_idx
            abs_end = chunk_start + end_idx
            
            CONTEXT_PADDING = 200
            # We calculate boundaries relative to the 4000-tick chunk
            slice_start = max(0, start_idx - CONTEXT_PADDING)
            slice_end = min(chunksize, end_idx + CONTEXT_PADDING)
            
            # 3. CHOP
            chopped_clean_input = clean_input[:, :, slice_start:slice_end]
            chopped_corrupt_input = corrupted_input[:, :, slice_start:slice_end]
            
            # 4. DECODE CLEAN CHOPPED SLICE
            with model.trace(chopped_clean_input):
                chopped_clean_proxy = model.output.save()
            chopped_clean_str = bonito_model.decode(chopped_clean_proxy.detach()[:, 0, :])
            
            # 5. DECODE CORRUPT CHOPPED SLICE
            with model.trace(chopped_corrupt_input):
                chopped_corrupt_proxy = model.output.save()
            chopped_corrupt_str = bonito_model.decode(chopped_corrupt_proxy.detach()[:, 0, :])
            
            # 6. COMPARE
            is_valid, hbegin_idx, clean_l, corrupt_l = is_strictly_one_replacement_in_chopped_slice(
                chopped_clean_str, 
                chopped_corrupt_str, 
                target_base=cand['base']
            )

            if is_valid:
                print(f"Success! Negative Control Substitution: {clean_l} mutated to {corrupt_l} at string idx {hbegin_idx}")
                
                # Update your records dictionary:
                # 'Base Letter': f"{clean_l}->{corrupt_l}",
                # 'Type': "Negative_Control_Substitution",

                records.append({
                    # 'base': f"['{base_l}']",
                    'clean base': clean_l,
                    'corrupt base': corrupt_l,
                    'num_bases': '[1]',
                    'duration_viterbi': cand['end_t'] - cand['start_t'],
                    'raw start idx': abs_start, 
                    'raw end idx': abs_end,
                    'input_base_timestamps': f"[{abs_start}]",
                    'Dampen width': 1.0,
                    'Scale Factor': scale,
                    'Clean string': chopped_clean_str,       # Fixed to use chopped string
                    'Corrupt_string': chopped_corrupt_str,   # Fixed to use chopped string
                    'H Begin Idx': hbegin_idx, 
                    # 'Base Letter': base_l,
                    'Clean H-er Length': 1, 
                    'Corrupt H-er Length': 0,
                    'Type': "Negative_Control",
                    'Corruption Start Raw': abs_start,
                    'Corruption End Raw': abs_end,
                    'Noise source idx': None,
                    'Insert idx': None
                })
                break

    del clean_output_proxy

